        printLongLongLine(data[0]);

        int64_t * oldData = data;
        data = (int64_t *)realloc(data, (130000)*sizeof(int64_t));
        if (data != NULL)
        {
            if (data != oldData)
            {
                free(oldData);
            }
            data[0] = 10LL;
            printLongLongLine(data[0]);
            free(data);
        }
        else
        {
            free(oldData);
        }
